let childReportDraft=null,childReportBusy=false;
const childReportSections=[['objective','Objetivo'],['learning','1. Aprendizagem'],['attention','2. Foco e atenção'],['behavior','3. Comportamento'],['conclusion','4. Considerações finais']];
const childReportFields=[['title','Título do relatório'],['child','Nome da criança'],['className','Turma'],['teacher','Professor(a) da turma'],['period','Período observado'],['recipient','Destinatário / finalidade'],['author','Nome de quem escreveu'],['role','Cargo / função de quem escreveu'],['city','Local'],['date','Data de emissão']];
window.renderChildReports=root=>{root.innerHTML=`<div class="panel"><h2>Relatório avaliativo da criança</h2><p>Registre as observações pedagógicas e prepare um relatório para a família, com papel timbrado e assinatura de quem o escreveu.</p><button class="primary" onclick="openChildReport()">+ Criar relatório avaliativo</button></div><div class="panel docs-archive"><div class="archive-head"><h3>Relatórios salvos</h3><input id="childReportSearch" class="archive-search" aria-label="Pesquisar relatórios" placeholder="Pesquisar criança, turma ou autoria…" oninput="filterChildReports()"></div><div id="childReportArchive"></div></div>`;filterChildReports()};
window.filterChildReports=()=>{const root=document.getElementById('childReportArchive');if(!root)return;const q=(document.getElementById('childReportSearch')?.value||'').toLocaleLowerCase('pt-BR');const records=(state.generatedDocs||[]).filter(g=>g.template==='relatorioAvaliativo'&&childReportText(g.data).toLocaleLowerCase('pt-BR').includes(q)).sort((a,b)=>(b.updatedAt||b.createdAt||'').localeCompare(a.updatedAt||a.createdAt||''));root.innerHTML=records.length?`<div class="history-table-wrap"><table class="table"><thead><tr><th>Relatório</th><th>Data</th><th>Ações</th></tr></thead><tbody>${records.map(g=>`<tr><td><b>${esc(childReportText(g.data).slice(0,140))}</b></td><td>${esc(g.date)}</td><td class="oficio-row-actions"><button onclick="previewGenerated('${g.id}')">Visualizar e imprimir</button><button onclick="reopenGenerated('${g.id}')">Editar e imprimir</button><button class="danger" onclick="deleteGeneratedDoc('${g.id}')">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Nenhum relatório encontrado.</p>'};
window.closeChildReport=()=>{if(childReportBusy)return;if(!confirm('Fechar o formulário? Alterações que ainda não foram salvas serão descartadas.'))return;document.getElementById('childReportModal').classList.add('hidden');childReportDraft=null};
function childReportExample(name){const n=name||'[Nome da criança]';return {objective:`Apresentar informações sobre a aprendizagem, o foco, a atenção e o comportamento de ${n} no contexto escolar, com base nas observações realizadas durante as atividades e experiências cotidianas da Educação Infantil, a fim de contribuir com o acompanhamento da criança e com o diálogo entre a família e a escola.`,learning:`${n} demonstra interesse pelas propostas pedagógicas e acompanha as experiências desenvolvidas com a turma, apresentando avanços importantes em seu processo de aprendizagem. Reconhece, associa, diferencia e escreve seu próprio nome, demonstrando familiaridade com essa referência escrita. Também realiza atividades de cópia de letras e palavras apresentadas no quadro, acompanhando as propostas realizadas em sala.

Durante as contações de histórias, demonstra interesse pelo conteúdo apresentado e participa dos momentos de reconto, contribuindo com a retomada das narrativas. Nas brincadeiras direcionadas e nas atividades coletivas, compreende os encaminhamentos propostos e participa de acordo com as orientações oferecidas.

De maneira geral, acompanha as atividades pedagógicas desenvolvidas com a turma e demonstra recursos para realizar as propostas apresentadas, evidenciando envolvimento e interesse pelas oportunidades de aprendizagem.`,attention:`No cotidiano escolar, ${n} demonstra capacidade de direcionar sua atenção para diferentes propostas pedagógicas, especialmente durante as contações de histórias, os momentos de reconto e as atividades que despertam seu interesse. Nessas situações, acompanha o desenvolvimento das propostas e participa quando são oferecidas oportunidades de interação.

Nas atividades de linguagem escrita, como o reconhecimento e a escrita do próprio nome e a cópia de letras e palavras do quadro, demonstra interesse e envolvimento na realização das tarefas, frequentemente mostrando-se disposto(a) a iniciar as atividades. Em algumas situações, necessita que as orientações sejam retomadas ou explicadas individualmente. Com a mediação e os esclarecimentos necessários, consegue dar continuidade à proposta, sendo importante observar como responde às instruções e ao acompanhamento oferecido durante a execução das tarefas.

Nas brincadeiras direcionadas, acompanha as orientações e participa das experiências organizadas pela professora. Considerando as situações observadas, consegue manter-se envolvido(a) em diferentes atividades da rotina escolar. Este registro se refere ao seu desempenho nos contextos observados, não constituindo uma avaliação clínica de sua atenção ou de suas funções executivas.`,behavior:`${n} acompanha a rotina da turma e participa das propostas realizadas em sala e nos momentos de brincadeira direcionada. No contexto escolar, demonstra condições favoráveis para envolver-se nas atividades coletivas, acompanhar os encaminhamentos da professora e participar das experiências pedagógicas.

Em situações que envolvem histórias com elementos assustadores, como algumas narrativas do folclore brasileiro, demonstra maior sensibilidade emocional, manifestando preocupação e medo. Nesses momentos, necessita de acolhimento e segurança para lidar com as emoções despertadas pela narrativa.

Em relação à alimentação, apresenta variações na aceitação dos alimentos oferecidos. Em alguns dias, demonstra maior seletividade; em outros, aceita diferentes opções, especialmente quando observa colegas próximos consumindo os alimentos disponibilizados. Essa variação é registrada como uma observação do cotidiano escolar, sem atribuir uma causa específica ao comportamento.

De modo geral, nas situações acompanhadas pela professora, participa das atividades e brincadeiras propostas, demonstrando envolvimento com a rotina e com as experiências vivenciadas pelo grupo.`,conclusion:`Com base nas observações, ${n} demonstra interesse pelas propostas pedagógicas, acompanha as atividades desenvolvidas com a turma e apresenta avanços relacionados ao reconhecimento e à escrita do próprio nome, bem como à cópia de letras, palavras e ilustrações. Também demonstra atenção e participação durante as contações de histórias, os momentos de reconto e as brincadeiras direcionadas.

Quanto ao foco e à atenção, observa-se que consegue envolver-se nas atividades propostas, especialmente naquelas que despertam seu interesse. Em relação ao comportamento, participa da rotina escolar e das experiências coletivas, apresentando, em situações específicas, maior sensibilidade diante de narrativas assustadoras e variações na aceitação alimentar.

Ressalta-se que este relatório descreve aspectos observados no ambiente escolar, considerando as situações vivenciadas no cotidiano da criança. As informações aqui registradas têm caráter pedagógico e podem contribuir para o diálogo com a família e, quando necessário, com os profissionais que acompanham a criança, não tendo a finalidade de confirmar ou descartar hipóteses diagnósticas.

A escola segue valorizando suas potencialidades, respeitando suas particularidades e oferecendo experiências que favoreçam seu desenvolvimento, sua aprendizagem e sua participação na vida coletiva.`}}
window.saveChildReport=async print=>{if(childReportBusy)return;if(!document.getElementById('childReportForm').reportValidity())return;const d=readChildReport();if(!reportHTMLText(d.bodyHtml).trim())return alert('Preencha o corpo do relatório.');let popup=null;if(print){popup=window.open('','_blank');if(!popup)return alert('Permita a abertura da janela de impressão para este site.');popup.document.write('<p>Salvando relatório…</p>');popup.document.close()}childReportBusy=true;document.querySelectorAll('#childReportModal button').forEach(b=>b.disabled=true);const status=document.getElementById('childReportStatus');status.textContent='Salvando no servidor…';try{await sharedQueue;if(!sharedActive)throw Error('Conecte à base compartilhada em Segurança antes de salvar.');const index=state.generatedDocs.findIndex(g=>g.id===childReportDraft.id),record=childReportRecord(d,childReportDraft.id,state.generatedDocs[index]);if(index<0)state.generatedDocs.push(record);else state.generatedDocs[index]=record;await writeDataFile(false);await sharedQueue;if(!sharedActive||localStorage.getItem('cei-shared-dirty')==='1')throw Error('O servidor não confirmou a gravação. O rascunho foi preservado; tente novamente.');status.textContent='Relatório salvo no servidor.';filterChildReports();if(print)openChildReportPrint(d,popup);notify('Relatório salvo.')}catch(error){popup?.close();status.textContent=error.message;alert(error.message)}finally{childReportBusy=false;document.querySelectorAll('#childReportModal button').forEach(b=>b.disabled=false)}};
function childReportDate(date){const [y,m,d]=String(date||'').split('-').map(Number);if(!y||!m||!d)return '';return new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(y,m-1,d)))}
function openChildReportPrint(data,popup){const win=popup||window.open('','_blank');if(!win)return alert('Permita abrir a janela de impressão para este site.');win.document.open();win.document.write(childReportPrintHTML(data));win.document.close()}
documentTemplates.relatorioAvaliativo={icon:'📝',name:'Relatório avaliativo da criança',description:'Aprendizagem, foco, atenção e comportamento; papel timbrado e assinatura.',fields:[]};
const reportPreviousOpen=window.openDocGen,reportPreviousPreview=window.previewGenerated,reportPreviousEdit=window.reopenGenerated;
window.openDocGen=id=>id==='relatorioAvaliativo'?openChildReport():reportPreviousOpen(id);
window.previewGenerated=id=>{const record=state.generatedDocs.find(g=>g.id===id);return record?.template==='relatorioAvaliativo'?openChildReportPrint(record.data):reportPreviousPreview(id)};
window.reopenGenerated=id=>{const record=state.generatedDocs.find(g=>g.id===id);return record?.template==='relatorioAvaliativo'?openChildReport(id):reportPreviousEdit(id)};
document.body.insertAdjacentHTML('beforeend',`<div id="childReportModal" class="modal hidden" role="dialog" aria-modal="true" aria-labelledby="childReportHeading"><div class="modal-card wide child-report-card"><h2 id="childReportHeading">Relatório avaliativo da criança</h2><form id="childReportForm" onsubmit="event.preventDefault();saveChildReport(false)"></form><p id="childReportStatus" role="status" aria-live="polite"></p><div class="actions child-report-actions"><button onclick="closeChildReport()">Fechar</button><button onclick="previewChildReportDraft()">Visualizar rascunho</button><button onclick="saveChildReport(false)">Salvar relatório</button><button class="primary" onclick="saveChildReport(true)">Salvar e visualizar impressão</button></div></div></div>`);

function reportToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function reportPlainHTML(text){return String(text||'').split(/\n\s*\n/).map(p=>'<p>'+esc(p).replace(/\n/g,'<br>')+'</p>').join('')}
function reportSanitize(html){const source=new DOMParser().parseFromString(String(html||''),'text/html');const out=document.createElement('div');const allowed=new Set(['P','DIV','BR','STRONG','B','EM','I','U','S','STRIKE','H1','H2','H3','H4','H5','H6','UL','OL','LI','BLOCKQUOTE','SPAN','SUP','SUB']);const drop=new Set(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','IMG','SVG','MATH','FORM','INPUT','BUTTON','VIDEO','AUDIO','LINK','META']);function copy(node,parent){if(node.nodeType===3){parent.append(document.createTextNode(node.textContent));return}if(node.nodeType!==1||drop.has(node.tagName))return;let target=parent;if(allowed.has(node.tagName)){target=document.createElement(node.tagName==='DIV'?'div':(['B','STRONG'].includes(node.tagName)&&node.style.fontWeight==='normal'?'span':node.tagName.toLowerCase()));const style=node.style;if(/^(center|right|left|justify)$/.test(style.textAlign))target.style.textAlign=style.textAlign;if(style.fontWeight==='bold'||Number(style.fontWeight)>=600)target.style.fontWeight='bold';if(style.fontStyle==='italic')target.style.fontStyle='italic';if(style.textDecoration.includes('underline'))target.style.textDecoration='underline';if(style.textDecoration.includes('line-through'))target.style.textDecoration='line-through';if(node.tagName==='OL'&&/^[0-9]{1,4}$/.test(node.getAttribute('start')||''))target.setAttribute('start',node.getAttribute('start'));parent.append(target)}for(const child of node.childNodes)copy(child,target)}for(const node of source.body.childNodes)copy(node,out);return out.innerHTML}
function reportHTMLText(html){const node=document.createElement('div');node.innerHTML=reportSanitize(html);return node.textContent}
function childReportDefaults(){return {version:3,title:'Relatório avaliativo da criança',child:'',className:'',year:reportToday().slice(0,4),period:'',professionals:[{name:'',role:'Professor(a)'}],bodyHtml:'',date:reportToday(),city:'Araquari'}}
function reportNormalize(old={}){const d={...childReportDefaults(),...old};if(!Array.isArray(old.professionals)||!old.professionals.length)d.professionals=[{name:old.author||old.teacher||'',role:old.role||'Professor(a)'}];if(typeof old.bodyHtml==='string')d.bodyHtml=reportSanitize(old.bodyHtml);else if(typeof old.text==='string')d.bodyHtml=reportPlainHTML(old.text);else d.bodyHtml=childReportSections.filter(([key])=>old[key]).map(([key,label])=>'<h2>'+esc(label)+'</h2>'+reportPlainHTML(old[key])).join('');delete d.text;return d}
function childReportText(d){const n=reportNormalize(d);return [n.title,n.child,n.className,n.year,n.period,...n.professionals.map(p=>p.name+' '+p.role),reportHTMLText(n.bodyHtml)].join(' ')}
window.openChildReport=id=>{const record=state.generatedDocs.find(g=>g.id===id&&g.template==='relatorioAvaliativo');childReportDraft={id:record?.id||uid(),data:reportNormalize(record?.data)};const d=childReportDraft.data;document.getElementById('childReportForm').innerHTML=`<p class="hint">Preencha a identificação e cole apenas o corpo do relatório no editor. Títulos, parágrafos, negrito, itálico e listas são preservados; fontes e margens seguem o padrão institucional.</p>${record?.data?.text!==undefined?'<p class="hint">Este relatório anterior foi preservado integralmente no editor. Confira e transfira a identificação para os campos abaixo, se necessário.</p>':''}<fieldset><legend>Identificação da criança</legend><div class="form-grid">${[['title','Título do relatório'],['child','Nome da criança'],['className','Turma'],['year','Ano letivo'],['period','Período de observação']].map(([key,label])=>`<label class="${key==='title'?'full':''}">${label}<input data-report-field="${key}" required maxlength="250" value="${esc(d[key])}"></label>`).join('')}</div></fieldset><fieldset><legend>Profissionais responsáveis</legend><div id="reportProfessionals"></div><button type="button" onclick="reportAddProfessional()">+ Adicionar responsável</button></fieldset><div class="child-report-template"><button type="button" onclick="useChildReportExample()">Usar texto de exemplo</button><small>Revise as observações antes de entregar à família.</small></div><label id="reportBodyLabel" class="child-report-section">Corpo do relatório</label><div class="report-editor-toolbar" role="toolbar" aria-label="Formatação do relatório">${[['bold','Negrito'],['italic','Itálico'],['underline','Sublinhado'],['insertUnorderedList','Lista'],['insertOrderedList','Lista numerada'],['justifyLeft','Alinhar à esquerda'],['justifyCenter','Centralizar'],['justifyFull','Justificar']].map(([cmd,label])=>`<button type="button" onmousedown="event.preventDefault()" onclick="reportFormat('${cmd}')">${label}</button>`).join('')}<button type="button" onmousedown="event.preventDefault()" onclick="reportFormat('formatBlock','h2')">Título</button><button type="button" onmousedown="event.preventDefault()" onclick="reportFormat('formatBlock','p')">Parágrafo</button><button type="button" onmousedown="event.preventDefault()" onclick="reportFormat('removeFormat')">Limpar formatação</button></div><div id="reportBodyEditor" class="report-rich-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-labelledby="reportBodyLabel" spellcheck="true">${d.bodyHtml}</div><p class="hint">Araquari e a data por extenso são inseridas automaticamente na emissão. As assinaturas são geradas conforme os profissionais, com 2,2 cm livres para assinatura Gov.br. Reimpressões mantêm a data salva.</p>`;renderReportProfessionals();const editor=document.getElementById('reportBodyEditor');editor.addEventListener('paste',event=>{event.preventDefault();const html=event.clipboardData.getData('text/html');document.execCommand('insertHTML',false,html?reportSanitize(html):reportPlainHTML(event.clipboardData.getData('text/plain')))});editor.addEventListener('drop',event=>event.preventDefault());document.getElementById('childReportStatus').textContent='';document.getElementById('childReportModal').classList.remove('hidden')};
function renderReportProfessionals(){document.getElementById('reportProfessionals').innerHTML=childReportDraft.data.professionals.map((p,i)=>`<div class="report-professional"><label>Nome do responsável ${i+1}<input data-prof-name="${i}" required maxlength="200" value="${esc(p.name)}"></label><label>Cargo / função<input data-prof-role="${i}" required maxlength="150" value="${esc(p.role)}"></label><button type="button" ${i===0?'disabled':''} onclick="reportRemoveProfessional(${i})" aria-label="Remover responsável ${i+1}">Remover</button></div>`).join('')}
function reportReadProfessionals(){return Array.from(document.querySelectorAll('[data-prof-name]')).map((el,i)=>({name:el.value.trim(),role:document.querySelector(`[data-prof-role="${i}"]`).value.trim()}))}
window.reportAddProfessional=()=>{childReportDraft.data.professionals=reportReadProfessionals();childReportDraft.data.professionals.push({name:'',role:''});renderReportProfessionals()};
window.reportRemoveProfessional=i=>{childReportDraft.data.professionals=reportReadProfessionals();childReportDraft.data.professionals.splice(i,1);renderReportProfessionals()};
window.reportFormat=(command,value)=>{const editor=document.getElementById('reportBodyEditor'),selection=window.getSelection();const range=selection?.rangeCount&&editor.contains(selection.anchorNode)&&editor.contains(selection.focusNode)?selection.getRangeAt(0).cloneRange():null;const align={justifyFull:'justify',justifyLeft:'left',justifyCenter:'center'}[command];if(align){const selected=range&&!range.collapsed;const blocks=Array.from(editor.querySelectorAll('p,div,h1,h2,h3,h4,h5,h6,li,blockquote'));const targets=selected?blocks.filter(el=>range.intersectsNode(el)):blocks;if(!selected)editor.style.textAlign=align;for(const el of targets){el.style.textAlign=align;el.removeAttribute('align')}if(!blocks.length){const p=document.createElement('p');while(editor.firstChild)p.append(editor.firstChild);p.style.textAlign=align;editor.append(p)}editor.focus();if(range){selection.removeAllRanges();selection.addRange(range)}return}editor.focus();if(range){selection.removeAllRanges();selection.addRange(range)}document.execCommand(command,false,value||null)};
function readChildReport(){const d=childReportDraft.data;for(const el of document.querySelectorAll('[data-report-field]'))d[el.dataset.reportField]=el.value.trim();d.professionals=reportReadProfessionals();const editor=document.getElementById('reportBodyEditor');d.bodyHtml=reportSanitize(editor.innerHTML);d.version=3;return d}
window.useChildReportExample=()=>{if(!confirm('Substituir o corpo pelo exemplo? Mantenha somente as observações que correspondem à criança.'))return;const name=document.querySelector('[data-report-field="child"]').value.trim();const example=childReportExample(name);document.getElementById('reportBodyEditor').innerHTML=childReportSections.map(([key,label])=>'<h2>'+esc(label)+'</h2>'+reportPlainHTML(example[key])).join('')};
function childReportRecord(data,id,existing){const now=new Date().toISOString();const d=structuredClone(data);d.date=existing?.data?.date||d.date||reportToday();d.city='Araquari';return {ownerEmail:existing?.ownerEmail||window.CEI_SESSION?.email,id,template:'relatorioAvaliativo',name:d.title,date:formatDate(d.date),reference:d.child+' — '+d.className,data:d,createdAt:existing?.createdAt||now,updatedAt:now}}
window.previewChildReportDraft=()=>{if(!document.getElementById('childReportForm').reportValidity())return;const d=readChildReport();if(!reportHTMLText(d.bodyHtml).trim())return alert('Preencha o corpo do relatório.');openChildReportPrint(d)};
function childReportPrintHTML(input){const d=reportNormalize(input);const signatures=[];for(let i=0;i<d.professionals.length;i+=2)signatures.push('<div class="report-signature-row">'+d.professionals.slice(i,i+2).map(p=>'<div class="report-signature"><div class="report-signature-line"></div><b>'+esc(p.name)+'</b><div>'+esc(p.role)+'</div></div>').join('')+'</div>');return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(d.title)}</title><link rel="stylesheet" href="${location.origin}/child-report-print.css?v=20261021-rich1"><script src="${location.origin}/child-report-pagination.js?v=20261021-flow1" defer><\/script></head><body><div class="report-controls"><button id="reportPrint" disabled onclick="window.print()">Imprimir / Salvar PDF</button><span id="reportPrintStatus">Preparando páginas…</span></div><div id="reportSource" hidden><h1 class="report-title">${esc(d.title)}</h1><section class="report-identification">${[['Criança',d.child],['Turma',d.className],['Ano letivo',d.year],['Período de observação',d.period]].filter(([,v])=>v).map(([label,v])=>'<p><b>'+label+':</b> '+esc(v)+'</p>').join('')}</section><div id="reportBodySource">${reportSanitize(d.bodyHtml)}</div><p class="report-date">Araquari, ${esc(childReportDate(d.date))}.</p>${signatures.join('')}</div><div id="reportPages"></div></body></html>`}
